// ─────────────────────────────────────────────
// 1. 입력 처리
// ─────────────────────────────────────────────
const fs = require("fs");
const raw = fs.readFileSync(0, "utf8").trim().split(/\s+/).map(Number);

// 9x9 스도쿠 판 생성
const board = Array.from({ length: 9 }, () => Array(9).fill(0));

let idx = 0;
for (let i = 0; i < 9; i++) {
  for (let j = 0; j < 9; j++) {
    board[i][j] = raw[idx++];
  }
}

// ─────────────────────────────────────────────
// 2. 행/열/3x3 박스 사용 여부 체크 배열
// ─────────────────────────────────────────────
//
// rowUsed[r][num] = r번째 행에 숫자 num이 쓰였는지
// colUsed[c][num] = c번째 열에 숫자 num이 쓰였는지
// boxUsed[b][num] = b번째 3x3 박스에 숫자 num이 쓰였는지
//
// * 박스 인덱스 계산:
//   - r, c가 주어졌을 때,
//   - box = Math.floor(r / 3) * 3 + Math.floor(c / 3)
//   - 예: (0~2, 0~2) -> 0, (0~2, 3~5) -> 1, ...
//
const rowUsed = Array.from({ length: 9 }, () => Array(10).fill(false));
const colUsed = Array.from({ length: 9 }, () => Array(10).fill(false));
const boxUsed = Array.from({ length: 9 }, () => Array(10).fill(false));

// 아직 채워야 할 빈칸들의 좌표를 저장
const blanks = [];

// 초기 상태에서 사용 중인 숫자들 표시 + 빈칸 목록 만들기
for (let r = 0; r < 9; r++) {
  for (let c = 0; c < 9; c++) {
    const val = board[r][c];
    if (val === 0) {
      // 빈칸이면 좌표 저장
      blanks.push([r, c]);
    } else {
      // 이미 숫자가 있다면 사용 여부 체크
      const b = Math.floor(r / 3) * 3 + Math.floor(c / 3);
      rowUsed[r][val] = true;
      colUsed[c][val] = true;
      boxUsed[b][val] = true;
    }
  }
}

// 정답을 찾았는지 여부
let solved = false;
let output = "";

// ─────────────────────────────────────────────
// 3. 백트래킹(DFS) 함수 정의
// ─────────────────────────────────────────────
//
// dfs(pos)
//  - pos: blanks 배열에서 몇 번째 빈칸을 채우는 중인지 (0 ~ blanks.length)
//
// 알고리즘:
//  - pos가 빈칸 개수와 같아지면 모든 칸을 채운 것이므로 스도쿠 완성
//  - 현재 빈칸 (r, c)에 1~9 중 올 수 있는 숫자를 전부 시도
//  - 행/열/박스에서 사용 중인지 미리 체크해 가지치기
//
function dfs(pos) {
  // 이미 정답을 찾았으면 추가 탐색은 중단
  if (solved) return;

  // 모든 빈칸을 다 채운 경우
  if (pos === blanks.length) {
    solved = true;
    // board를 문자열로 만들어 저장
    const lines = board.map((row) => row.join(" "));
    output = lines.join("\n");
    return;
  }

  const [r, c] = blanks[pos];
  const b = Math.floor(r / 3) * 3 + Math.floor(c / 3);

  // 1 ~ 9까지 숫자 시도
  for (let num = 1; num <= 9; num++) {
    // 현재 행/열/박스에 이 숫자가 이미 쓰였으면 불가능
    if (rowUsed[r][num] || colUsed[c][num] || boxUsed[b][num]) continue;

    // num을 (r, c)에 놓는다고 가정
    board[r][c] = num;
    rowUsed[r][num] = true;
    colUsed[c][num] = true;
    boxUsed[b][num] = true;

    // 다음 빈칸으로 진행
    dfs(pos + 1);

    // 정답을 찾았으면 더 이상 되돌릴 필요 없이 리턴
    if (solved) return;

    // 백트래킹: 원상복구
    board[r][c] = 0;
    rowUsed[r][num] = false;
    colUsed[c][num] = false;
    boxUsed[b][num] = false;
  }
}

// ─────────────────────────────────────────────
// 4. DFS 시작 및 결과 출력
// ─────────────────────────────────────────────
dfs(0);
console.log(output);

// ─────────────────────────────────────────────
// 1. 입력 처리
// ─────────────────────────────────────────────
const fs = require("fs");
const N = Number(fs.readFileSync(0, "utf8").trim());

// ─────────────────────────────────────────────
// 2. 필요한 자료구조 준비
// ─────────────────────────────────────────────
//
// N-Queen 규칙
// - 하나의 행(row)에는 퀸 1개만 둔다.
// - 같은 열(column)에는 둘 수 없다.
// - 같은 대각선(diagonal)에도 둘 수 없다.
//
// 따라서, 현재까지 놓인 퀸들의
//  1) 사용 중인 열
//  2) 사용 중인 ↘ 대각선 (row + col)
//  3) 사용 중인 ↗ 대각선 (row - col + (N - 1))
// 을 기록해두고, 이미 사용 중이면 놓지 않도록 한다.
//

// 각 열(column)에 퀸이 있는지 여부
const colUsed = new Array(N).fill(false);

// ↘ 방향 대각선 (row + col) 인덱스는 0 ~ 2N-2 까지 가능하므로 길이 2N로 잡는다.
const diag1Used = new Array(2 * N).fill(false);

// ↗ 방향 대각선 (row - col + (N - 1)) 인덱스도 0 ~ 2N-2 까지 가능
const diag2Used = new Array(2 * N).fill(false);

// 정답(배치 가능한 경우의 수)을 저장할 변수
let answer = 0;

// ─────────────────────────────────────────────
// 3. 백트래킹(DFS) 함수 정의
// ─────────────────────────────────────────────
//
// row: 현재 몇 번째 행에 퀸을 놓을 차례인지 (0 ~ N-1)
//
// 아이디어:
//  - 한 행에는 퀸 하나만 놓는다고 가정하고,
//    row를 0부터 N-1까지 하나씩 늘려가며 퀸을 놓는다.
//  - 각 행에서 가능한 모든 열을 시도해 본다.
//  - 만약 해당 열/대각선에 이미 퀸이 있으면 스킵한다.
//  - 마지막 행(N-1)까지 모두 유효하게 놓았다면 경우의 수 +1.
//
function dfs(row) {
  // 마지막 행까지 퀸을 모두 놓은 경우
  if (row === N) {
    answer++;
    return;
  }

  // 현재 행(row)에서 0번 열부터 N-1번 열까지 시도
  for (let c = 0; c < N; c++) {
    const d1 = row + c;         // ↘ 대각선 인덱스
    const d2 = row - c + (N - 1); // ↗ 대각선 인덱스

    // 이미 사용 중인 열/대각선이면 놓을 수 없음
    if (colUsed[c] || diag1Used[d1] || diag2Used[d2]) continue;

    // 현재 위치 (row, c)에 퀸을 놓는다고 표시
    colUsed[c] = true;
    diag1Used[d1] = true;
    diag2Used[d2] = true;

    // 다음 행으로 진행
    dfs(row + 1);

    // 백트래킹: 다른 경우를 위해 다시 원상복구
    colUsed[c] = false;
    diag1Used[d1] = false;
    diag2Used[d2] = false;
  }
}

// ─────────────────────────────────────────────
// 4. DFS 시작 및 결과 출력
// ─────────────────────────────────────────────
dfs(0);
console.log(answer);

const fs = require("fs");

// 입력: 한 줄에 정수 N
const input = fs.readFileSync(0, "utf8").trim();
const N = Number(input);

// N x N 크기의 2차원 배열을 공백(' ')으로 초기화
// 나중에 '*'를 채우고 한 번에 문자열로 출력한다.
const board = Array.from({ length: N }, () => Array(N).fill(" "));

/**
 * 재귀적으로 별 패턴을 그리는 함수
 * @param {number} x    - 시작 행 인덱스
 * @param {number} y    - 시작 열 인덱스
 * @param {number} size - 현재 그릴 정사각형의 한 변 길이
 */
function drawStar(x, y, size) {
  // 가장 작은 단위(1x1)가 되면 별 하나 찍고 종료
  if (size === 1) {
    board[x][y] = "*";
    return;
  }

  // 현재 정사각형을 3등분한 크기
  const div = size / 3;

  // 3x3 격자 형태로 순회하면서 재귀 호출
  for (let i = 0; i < 3; i++) {
    for (let j = 0; j < 3; j++) {
      // 가운데 칸(1,1)은 공백으로 남겨둔다.
      if (i === 1 && j === 1) continue;

      // 나머지 8칸은 다시 같은 규칙으로 별을 그린다.
      drawStar(x + i * div, y + j * div, div);
    }
  }
}

// (0,0)부터 N x N 영역에 대해 패턴 그리기 시작
drawStar(0, 0, N);

// 2차원 배열을 한 줄씩 문자열로 합쳐서 출력
const result = board.map((row) => row.join("")).join("\n");
console.log(result);

// ─────────────────────────────────────────────
// 1. 입력 처리
// ─────────────────────────────────────────────
const fs = require("fs");
const input = fs.readFileSync(0, "utf8").trim();
const N = Number(input); // 원판 개수

// ─────────────────────────────────────────────
// 2. 하노이 재귀 함수 구현
// ─────────────────────────────────────────────

// 이동 과정을 담을 배열 (문자열 리스트)
const moves = [];

/**
 * 하노이 탑 재귀 함수
 * @param {number} n    - 옮겨야 할 원판 개수
 * @param {number} from - 출발 기둥 번호
 * @param {number} to   - 도착 기둥 번호
 * @param {number} via  - 보조 기둥 번호
 */
function hanoi(n, from, to, via) {
  // 원판이 1개인 경우: 바로 from -> to 로 옮기면 끝
  if (n === 1) {
    moves.push(`${from} ${to}`);
    return;
  }

  // 1) 가장 큰 원판을 제외한 n-1개를 보조 기둥(via)로 옮긴다.
  hanoi(n - 1, from, via, to);

  // 2) 가장 큰 원판 1개를 목적지 기둥(to)로 옮긴다.
  moves.push(`${from} ${to}`);

  // 3) 아까 보조 기둥으로 옮겨두었던 n-1개를 목적지 기둥(to)로 옮긴다.
  hanoi(n - 1, via, to, from);
}

// 하노이 알고리즘 실행 (1번 기둥 → 3번 기둥, 2번 기둥은 보조)
hanoi(N, 1, 3, 2);

// 총 이동 횟수: 2^N - 1
const count = Math.pow(2, N) - 1;

// 결과 출력: 첫 줄에 이동 횟수, 이후 줄마다 "from to"
console.log(count.toString());
console.log(moves.join("\n"));

function solution(progresses, speeds) {
    var answer = [];
    var days = progresses.map((progress, index) => 
        Math.ceil((100 - progress) / speeds[index]) // 각 작업이 완료되는 데 걸리는 일수 계산
    );

    var maxDay = days[0]; // 첫 번째 작업이 완료되는 날짜
    var count = 0; // 같은 날 배포될 작업 개수

    for (let i = 0; i < days.length; i++) {
        if (days[i] <= maxDay) {
            // 현재 작업이 이전 작업과 함께 배포될 수 있으면 count 증가
            count++;
        } else {
            // 이전 작업들 배포하고 새로운 기준 설정
            answer.push(count);
            count = 1; // 현재 작업이 새로운 배포의 시작
            maxDay = days[i]; // 기준일 변경
        }
    }

    answer.push(count); // 마지막 남은 작업들 배포
    return answer;
}

function solution(progresses, speeds) {
  var answer = [];
  var days = progresses.map(
    (progress, index) => Math.ceil((100 - progress) / speeds[index]) // 각 작업이 완료되는 데 걸리는 일수 계산
  );

  var maxDay = days[0]; // 첫 번째 작업이 완료되는 날짜
  var count = 0; // 같은 날 배포될 작업 개수

  for (let i = 0; i < days.length; i++) {
    if (days[i] <= maxDay) {
      // 현재 작업이 이전 작업과 함께 배포될 수 있으면 count 증가
      count++;
    } else {
      // 이전 작업들 배포하고 새로운 기준 설정
      answer.push(count);
      count = 1; // 현재 작업이 새로운 배포의 시작
      maxDay = days[i]; // 기준일 변경
    }
  }

  answer.push(count); // 마지막 남은 작업들 배포
  return answer;
}

// 첫 줄에 N (1 ≤ N ≤ 100)이 주어진다.
const fs = require("fs");
const input = fs.readFileSync(0, "utf8").trim();
const N = Number(input);

// 문제에서 요구하는 나머지 값
const MOD = 1_000_000_000;

// DP 정의
// dp[i][d] = 길이가 i인 계단 수 중에서 마지막 자리가 d(0~9)인 것들의 개수
// 예) dp[3][2] = 길이 3, 맨 끝 숫자가 2인 계단 수 개수
const dp = Array.from({ length: N + 1 }, () => Array(10).fill(0));

// 초기값 설정 (길이 1인 계단 수)
// 한 자리 계단 수는 1~9 까지 가능 (0으로 시작하는 수는 허용 X)
for (let d = 1; d <= 9; d++) {
  dp[1][d] = 1;
}
// dp[1][0]은 0 (0으로 시작하는 수는 계단 수에서 제외)

// 점화식
// 길이가 i인 계단 수를 만들 때,
// 마지막 자리가 d일 수 있는 경우는 다음 두 가지다:
//
// 1) 바로 이전 자리(i-1 자리)의 마지막 숫자가 d-1 이었을 때
// 2) 바로 이전 자리(i-1 자리)의 마지막 숫자가 d+1 이었을 때
//
// 즉,
//   dp[i][0] = dp[i-1][1]
//   dp[i][9] = dp[i-1][8]
//   dp[i][d] = dp[i-1][d-1] + dp[i-1][d+1]  (1 <= d <= 8)
//
// 위 식을 MOD로 나눈 나머지로 관리한다.
for (let i = 2; i <= N; i++) {
  for (let d = 0; d <= 9; d++) {
    if (d === 0) {
      // 마지막이 0이라면 그 앞 자리는 무조건 1
      dp[i][d] = dp[i - 1][1] % MOD;
    } else if (d === 9) {
      // 마지막이 9라면 그 앞 자리는 무조건 8
      dp[i][d] = dp[i - 1][8] % MOD;
    } else {
      // 그 외 (1~8)은 양 옆 숫자에서 올 수 있음
      dp[i][d] = (dp[i - 1][d - 1] + dp[i - 1][d + 1]) % MOD;
    }
  }
}

// 정답 계산
// 길이가 N인 계단 수의 개수 = 마지막 자리가 0~9인 경우 모두 합친 값
let answer = 0;
for (let d = 0; d <= 9; d++) {
  answer = (answer + dp[N][d]) % MOD;
}

// 결과 출력
console.log(answer);

// ─────────────────────────────────────────────
// 1. 입력 처리
// ─────────────────────────────────────────────
const fs = require("fs");
const input = fs.readFileSync(0, "utf8").trim().split("\n");

const N = Number(input[0]); // 사람 수 (짝수)
const S = input
  .slice(1)
  .map((line) => line.split(" ").map(Number)); // 능력치 배열 S[i][j]

// 방문 배열: true면 '스타트 팀', false면 '링크 팀'
const visited = new Array(N).fill(false);

// 두 팀 능력치 차이의 최솟값
let answer = Infinity;

// ─────────────────────────────────────────────
// 2. 능력치 차이 계산 함수
// ─────────────────────────────────────────────
//
// 현재 visited 배열 상태대로
// 스타트 팀, 링크 팀의 능력치를 각각 계산해
// 두 값의 차이를 반환한다.
//
function calcDiff() {
  let start = 0; // 스타트 팀 능력치 합
  let link = 0;  // 링크 팀 능력치 합

  // i < j 인 쌍만 보면서 팀에 따라 능력치를 더한다.
  for (let i = 0; i < N; i++) {
    for (let j = i + 1; j < N; j++) {
      // 둘 다 스타트 팀
      if (visited[i] && visited[j]) {
        start += S[i][j] + S[j][i];
      }
      // 둘 다 링크 팀
      else if (!visited[i] && !visited[j]) {
        link += S[i][j] + S[j][i];
      }
    }
  }

  return Math.abs(start - link);
}

// ─────────────────────────────────────────────
// 3. 백트래킹으로 팀 나누기
// ─────────────────────────────────────────────
//
// dfs(idx, cnt)
//  - idx: 현재 고려 중인 사람 번호 (0 ~ N-1)
//  - cnt: 지금까지 스타트 팀에 넣은 사람 수
//
// 목표: 스타트 팀에 정확히 N/2 명을 고르는 모든 조합 탐색
//
function dfs(idx, cnt) {
  // 스타트 팀이 N/2명이 되면 능력치 차이를 계산
  if (cnt === N / 2) {
    const diff = calcDiff();
    if (diff < answer) answer = diff;
    return;
  }

  // 남은 사람 모두를 스타트 팀에 넣어도 N/2를 못 채우는 경우 가지치기
  if (idx >= N) return;

  // 현재 인덱스부터 N까지 순회하면서
  // 스타트 팀에 포함시킬 사람을 선택
  for (let i = idx; i < N; i++) {
    // 이미 스타트 팀에 포함된 사람은 건너뛸 필요는 없지만
    // visited로 분기하므로 중복 선택은 자연스럽게 방지된다.
    visited[i] = true;         // i번 사람을 스타트 팀에 넣는다
    dfs(i + 1, cnt + 1);       // 다음 사람 선택하러 이동
    visited[i] = false;        // 백트래킹: 다시 원상복구
  }
}

// ─────────────────────────────────────────────
// 4. 대칭 경우 제거 최적화
// ─────────────────────────────────────────────
//
// 팀을 나눌 때, 사람 0이 스타트 팀에 있든 링크 팀에 있든
