// 점화식 적용 (Bottom-Up)
// i를 1로 만드는 최소 연산 횟수는 다음 세 가지 경우 중 최소값:
// 1) i - 1 로 만들고 한 번 더 빼기 → dp[i-1] + 1
// 2) i 가 2로 나누어 떨어질 때: i / 2 로 만든 뒤 두 배 → dp[i/2] + 1
// 3) i 가 3으로 나누어 떨어질 때: i / 3 로 만든 뒤 세 배 → dp[i/3] + 1
for (let i = 2; i <= N; i++) {
  // 기본 연산: 1을 빼는 경우
  let minOps = dp[i - 1] + 1;

  // 2로 나누어 떨어질 경우 비교
  if (i % 2 === 0) {
