}

// 병합 과정에서 사용할 임시 배열 (한 번만 생성해서 재사용)
const tmp = new Array(N + 1);

// 몇 번 저장했는지 세는 카운터
let saveCount = 0;

// K번째 저장된 값을 기록할 변수 (기본값은 -1)
let answer = -1;

