// 첫 줄: A와 B의 원소 개수 (n, m)
const [n, m] = input[0].split(' ').map(Number);

// 둘째 줄: 집합 A의 원소들
const A = new Set(input[1].split(' ').map(Number));

// 셋째 줄: 집합 B의 원소들
const B = new Set(input[2].split(' ').map(Number));

// 대칭 차집합 구하기
// A에서 B에 없는 값들 + B에서 A에 없는 값들
let count = 0;

for (let value of A) {
  if (!B.has(value)) {
    count++; // A에는 있지만 B에는 없는 원소
  }
}

for (let value of B) {
  if (!A.has(value)) {
    count++; // B에는 있지만 A에는 없는 원소
  }
}

// 결과 출력
console.log(count);

const fs = require("fs");
const input = fs.readFileSync(0, "utf8").trim().split("\n");
const n = Number(input[0]);

// 덱 저장소와 포인터
const dq = {};    // 인덱스: 정수, 값: 정수
let head = 0;     // 현재 덱의 "앞" 인덱스
let tail = 0;     // 현재 덱의 "뒤" 다음 인덱스 (비어있으면 head===tail)

// 유틸
const size = () => tail - head;

const out = [];
for (let i = 1; i <= n; i++) {
  const line = input[i];
  const sp = line.split(" ");
  const cmd = Number(sp[0]);

  if (cmd === 1) {
    // 1 X: 정수 X를 덱의 앞에 넣는다.
    const x = Number(sp[1]);
    dq[--head] = x;
  } else if (cmd === 2) {
    // 2 X: 정수 X를 덱의 뒤에 넣는다.
    const x = Number(sp[1]);
    dq[tail++] = x;
  } else if (cmd === 3) {
    // 3: 맨 앞의 정수를 빼고 출력, 없으면 -1
    if (size() === 0) out.push(-1);
    else {
      const v = dq[head];
      delete dq[head++];
      out.push(v);
    }
  } else if (cmd === 4) {
    // 4: 맨 뒤의 정수를 빼고 출력, 없으면 -1
    if (size() === 0) out.push(-1);
    else {
      const v = dq[--tail];
      delete dq[tail];
      out.push(v);
    }
  } else if (cmd === 5) {
    // 5: 덱에 들어있는 정수의 개수
    out.push(size());
  } else if (cmd === 6) {
    // 6: 덱이 비어있으면 1, 아니면 0
    out.push(size() === 0 ? 1 : 0);
  } else if (cmd === 7) {
    // 7: 맨 앞의 정수 출력, 없으면 -1
    out.push(size() === 0 ? -1 : dq[head]);
  } else if (cmd === 8) {
    // 8: 맨 뒤의 정수 출력, 없으면 -1
    out.push(size() === 0 ? -1 : dq[tail - 1]);
  }
}

console.log(out.join("\n"));

