  for (let i = 0; i < K - 1; i++) {
    // front -> back
    q.push(q[head++]);
  }

  // 2) K번째 원소 제거: 현재 front를 정답에 추가
  ans.push(q[head++]);

  // (선택) 메모리 관리: head가 커졌을 때 앞부분 잘라 정리
  if (head > 10000 && head * 2 > q.length) {
