// 이분 탐색 함수 정의
function binarySearch(arr, target) {
  let left = 0;
  let right = arr.length - 1;

  while (left <= right) {
    const mid = Math.floor((left + right) / 2);

    if (arr[mid] === target) {
      return 1; // 숫자 찾음
    } else if (arr[mid] < target) {
      left = mid + 1; // 오른쪽 범위로 이동
    } else {
      right = mid - 1; // 왼쪽 범위로 이동
    }
  }

  return 0; // 숫자 없음
}

