// 최대공약수(GCD)를 구하는 함수 - 유클리드 호제법 사용
function gcd(a, b) {
  while (b !== 0n) {  // BigInt에서는 0 대신 0n 사용
    const temp = b;
    b = a % b;
    a = temp;
  }
  return a;
}

// 최소공배수(LCM)는 (A * B) / GCD(A, B)
function lcm(a, b) {
  return (a * b) / gcd(a, b);
}

